import React from 'react';
import './Hero.css';

export const Hero = () => {
  return (
    <section className="hero-section">

      {/* Layer 0 — Sky background image: full cover, no position shift */}
      <img
        src={process.env.PUBLIC_URL + '/bg%20hero.webp'}
        alt=""
        className="hero-bg"
        aria-hidden="true"
      />

      {/* Layer 1 — 6-stop vignette: dark top → clears mid → darkens at base */}
      <div className="hero-vignette" aria-hidden="true" />

      {/* Layer 2 — Content: heading, subtitle, button, dashboard */}
      <div className="nl-hero-content">
        <h1 className="nl-hero-heading">
          The intelligent travel companion<br />
          for <em>every journey you take.</em>
        </h1>
        <p className="nl-hero-subtitle">
          Your journey, our priority. Powered by AI, tailored for you.
        </p>
        <div className="nl-cta-row">
          <button id="nl-try-beta" className="nl-btn-hero-white">Join the Beta</button>
        </div>

        {/* Dashboard card */}
        <div className="hero-dashboard-wrapper">
          <img
            src={process.env.PUBLIC_URL + '/hero%20bg%20new.webp'}
            alt="Dishastra app dashboard"
            className="hero-dashboard"
          />
        </div>
      </div>

      {/* Layer 4 — Hills anchored to bottom, overlaps dashboard bottom
          Internal fade merges into the next section (#040404) */}
      <div className="hero-hills-wrapper" aria-hidden="true">
        <img
          src={process.env.PUBLIC_URL + '/image.webp'}
          alt=""
          className="hero-hills"
        />
        {/* Fade: transparent top → solid #040404 at very bottom (transition to next section) */}
        <div className="hero-hills-fade" />
      </div>

      {/* Layer 5 — Bottom section transition: hard fade below the hills into #040404 */}
      <div className="hero-section-fade" aria-hidden="true" />

    </section>
  );
};
